"""
aether_patch_importlib — 修补 Python 3.13 的 importlib 底层 bug
==============================================================
本机 Python 3.13 环境有几个互相关联的 importlib 兼容问题：
1. `importlib._bootstrap._find_spec` 对不存在的包会抛
   `TypeError: 'NoneType' object is not iterable`（DistutilsMetaFinder 引起）
2. `importlib_metadata._search_paths` 对 None paths 会抛同样错误
   （sentence-transformers 5.7.0 依赖的旧回吐包与 3.13 不兼容）

本模块在一切模型导入之前调用，安全修补这两处。
"""
import importlib._bootstrap as _b


def _patch_find_spec():
    if getattr(_b, "_aether_patched", False):
        return
    _orig_find_spec = _b._find_spec
    def _safe_find_spec(name, path, target=None):
        try:
            return _orig_find_spec(name, path, target)
        except TypeError:
            return None
    _b._find_spec = _safe_find_spec
    _b._aether_patched = True


def _patch_metadata_search_paths():
    """修补 importlib_metadata._search_paths，容错 None paths。"""
    try:
        import importlib_metadata
    except Exception:
        return
    if getattr(importlib_metadata, "_aether_patched", False):
        return
    _orig = importlib_metadata._search_paths
    def _safe_search_paths(name, paths=[]):
        if paths is None:
            paths = []
        try:
            return _orig(name, paths)
        except TypeError:
            return []
    importlib_metadata._search_paths = _safe_search_paths
    importlib_metadata._aether_patched = True


def _patch_metadata_from_name():
    """修补 importlib_metadata 的 from_name，容错 discover 失败。"""
    try:
        import importlib_metadata
    except Exception:
        return
    if getattr(importlib_metadata, "_aether_dist_patched", False):
        return
    try:
        _orig_from_name = importlib_metadata.Distribution.from_name
        def _safe_from_name(cls, name, **kwargs):
            try:
                return _orig_from_name(name, **kwargs)
            except (TypeError, StopIteration):
                raise importlib_metadata.PackageNotFoundError(name)
        importlib_metadata.Distribution.from_name = classmethod(_safe_from_name)
        importlib_metadata._aether_dist_patched = True
    except Exception:
        pass


def patch():
    _patch_find_spec()
    _patch_metadata_search_paths()
    _patch_metadata_from_name()


patch()
